#nullable enable

using System.Text;

namespace FlyleafLib.MediaPlayer;

public static class FasterWhisperDevicePolicy
{
    public static bool RequiresGpuAdmission(Config config)
    {
        if (config.Subtitles.ASREngine != SubASREngineType.FasterWhisper) return false;
        return !HasExplicitCpuDevice(FasterWhisperASRService.BuildCommand(
            config.Subtitles.FasterWhisperConfig, config.Subtitles.WhisperConfig).Arguments);
    }

    // Scan the effective command, including escaped quotes in values generated by CliWrap.
    // Give up on ambiguous forms. An unnecessary permit is preferable to an untracked GPU launch.
    internal static bool HasExplicitCpuDevice(string arguments)
    {
        List<string>? tokens = ReadArguments(arguments);
        if (tokens == null) return false;
        int deviceCount = 0;
        for (int index = 0; index < tokens.Count; index++)
        {
            string token = tokens[index];
            if (token == "--") return false;
            if (!token.StartsWith("--", StringComparison.Ordinal)) continue;

            int equals = token.IndexOf('=');
            string option = equals < 0 ? token : token[..equals];
            // The optional prompt is free text and may look like an option.
            if (option == "--initial_prompt" && equals < 0)
            {
                if (++index >= tokens.Count || tokens[index].StartsWith("--", StringComparison.Ordinal)) return false;
                continue;
            }
            if (option == "--device")
            {
                string? value = equals >= 0 ? token[(equals + 1)..] : ++index < tokens.Count ? tokens[index] : null;
                if (value != "cpu" || ++deviceCount != 1) return false;
            }
            else if ("--device".StartsWith(option, StringComparison.Ordinal) ||
                string.Equals(option, "--device", StringComparison.OrdinalIgnoreCase)) return false;
        }
        return deviceCount == 1;
    }

    // ProcessStartInfo.Arguments uses Windows-style double quotes and backslash parity on both targets.
    // Adjacent nonempty quote transitions can differ in native parsers. Treat them as ambiguous.
    internal static List<string>? ReadArguments(string command)
    {
        List<string> arguments = [];
        StringBuilder value = new();
        bool quoted = false, started = false;
        int backslashes = 0;
        bool previousQuote = false;
        foreach (char c in command)
        {
            if (char.IsControl(c) && c != '\t') return null;
            if (c == '\\') { backslashes++; started = true; previousQuote = false; continue; }
            if (c == '"')
            {
                value.Append('\\', backslashes / 2);
                if (backslashes % 2 == 0)
                {
                    if (previousQuote && value.Length > 0) return null;
                    quoted = !quoted;
                }
                else value.Append('"');
                previousQuote = backslashes % 2 == 0;
                backslashes = 0;
                started = true;
                continue;
            }

            previousQuote = false;
            value.Append('\\', backslashes);
            backslashes = 0;
            if (!quoted && c is ' ' or '\t')
            {
                if (started) arguments.Add(value.ToString());
                value.Clear();
                started = false;
                continue;
            }
            if (!quoted && char.IsWhiteSpace(c)) return null;
            value.Append(c);
            started = true;
        }
        if (quoted) return null;
        if (started) arguments.Add(value.Append('\\', backslashes).ToString());
        return arguments;
    }
}
